1	// "Login with Google" — Google OAuth 2.0 / OpenID Connect.
2	//
3	// Plain server-side module (NO "use server") — imported only by the two Google
4	// auth route handlers under app/api/auth/google. Never bundled to the client;
5	// no client secret or token is ever logged or returned to the browser.
6	//
7	// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
8	// Authorization Code flow with a client secret (client_secret_post). Google is
9	// the identity provider; we only ever ask for the user's identity, never any
10	// Google API scope beyond `openid email profile`.
11	//
12	// ---------------------------------------------------------------------------
13	// PROTOCOL CONSTANTS — Google's OIDC endpoints (stable, from
14	// https://accounts.google.com/.well-known/openid-configuration):
15	//   * authorize  https://accounts.google.com/o/oauth2/v2/auth
16	//   * token      https://oauth2.googleapis.com/token
17	//   * userinfo   https://openidconnect.googleapis.com/v1/userinfo
18	// ---------------------------------------------------------------------------
19	
20	import { randomBytes } from "node:crypto";
21	
22	export const GOOGLE_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
23	export const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";
24	export const GOOGLE_USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";
25	
26	/** The scopes we request: identity only. */
27	export const GOOGLE_OAUTH_SCOPES = "openid email profile";
28	
29	/** Random URL-safe string for the CSRF `state`. */
30	export function randomUrlSafe(bytes = 32): string {
31	  return randomBytes(bytes).toString("base64url");
32	}
33	
34	/**
35	 * Redirect URI — must be registered verbatim on the Google OAuth client.
36	 * `${APP_URL}/api/auth/google/callback`.
37	 */
38	export function googleRedirectUri(): string {
39	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
40	  return `${base}/api/auth/google/callback`;
41	}
42	
43	/**
44	 * Is the OAuth client configured in this environment? When false the login page
45	 * HIDES the "Continue with Google" button, so nothing shows a broken flow before
46	 * the operator adds the credentials. Read at request time (not module top-level)
47	 * so an unset value never crashes boot.
48	 */
49	export function googleOauthConfigured(): boolean {
50	  return Boolean(
51	    (process.env.GOOGLE_CLIENT_ID ?? "").trim() &&
52	      (process.env.GOOGLE_CLIENT_SECRET ?? "").trim(),
53	  );
54	}
55	
56	/** Build the Google consent URL for this sign-in attempt. */
57	export function googleAuthorizeUrl(opts: { state: string }): string {
58	  const url = new URL(GOOGLE_AUTHORIZE_URL);
59	  url.searchParams.set("client_id", (process.env.GOOGLE_CLIENT_ID ?? "").trim());
60	  url.searchParams.set("redirect_uri", googleRedirectUri());
61	  url.searchParams.set("response_type", "code");
62	  url.searchParams.set("scope", GOOGLE_OAUTH_SCOPES);
63	  url.searchParams.set("state", opts.state);
64	  // We do not need offline access (no Google API calls after sign-in), so ask
65	  // for an online-only grant and always let the user pick the account.
66	  url.searchParams.set("access_type", "online");
67	  url.searchParams.set("prompt", "select_account");
68	  return url.toString();
69	}
70	
71	// ---- Token endpoint --------------------------------------------------------
72	
73	type TokenResponse = {
74	  access_token?: string;
75	  id_token?: string;
76	  expires_in?: number;
77	  scope?: string;
78	  token_type?: string;
79	  error?: string;
80	  error_description?: string;
81	};
82	
83	/**
84	 * Exchange an authorization `code` for tokens (client_secret_post). Returns the
85	 * access token or a short, safe error string — NEVER the client secret or any
86	 * token in the error text.
87	 */
88	export async function googleExchangeCode(
89	  code: string,
90	): Promise<{ accessToken?: string; error?: string }> {
91	  const clientId = (process.env.GOOGLE_CLIENT_ID ?? "").trim();
92	  const clientSecret = (process.env.GOOGLE_CLIENT_SECRET ?? "").trim();
93	
94	  const params = new URLSearchParams({
95	    code,
96	    client_id: clientId,
97	    client_secret: clientSecret,
98	    redirect_uri: googleRedirectUri(),
99	    grant_type: "authorization_code",
100	  });
101	
102	  let res: Response;
103	  try {
104	    res = await fetch(GOOGLE_TOKEN_URL, {
105	      method: "POST",
106	      headers: {
107	        "Content-Type": "application/x-www-form-urlencoded",
108	        Accept: "application/json",
109	      },
110	      body: params.toString(),
111	      cache: "no-store",
112	    });
113	  } catch {
114	    return { error: "Couldn't reach Google to finish signing in. Try again shortly." };
115	  }
116	
117	  let parsed: TokenResponse | null = null;
118	  try {
119	    parsed = (await res.json()) as TokenResponse;
120	  } catch {
121	    parsed = null;
122	  }
123	
124	  if (!res.ok || !parsed?.access_token) {
125	    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
126	    return { error: `Google rejected the sign-in (${String(detail).slice(0, 160)}).` };
127	  }
128	
129	  return { accessToken: parsed.access_token };
130	}
131	
132	// ---- Userinfo --------------------------------------------------------------
133	
134	export type GoogleProfile = {
135	  sub: string;
136	  email: string;
137	  emailVerified: boolean;
138	  name: string;
139	  picture: string | null;
140	};
141	
142	type UserinfoResponse = {
143	  sub?: string;
144	  email?: string;
145	  email_verified?: boolean | string;
146	  name?: string;
147	  given_name?: string;
148	  picture?: string;
149	};
150	
151	/**
152	 * Fetch the signed-in user's profile from the OIDC userinfo endpoint with the
153	 * bearer access token. Returns the normalised profile or a safe error string.
154	 * `emailVerified` normalises Google's boolean-or-"true"-string form.
155	 */
156	export async function googleFetchProfile(
157	  accessToken: string,
158	): Promise<{ profile?: GoogleProfile; error?: string }> {
159	  let res: Response;
160	  try {
161	    res = await fetch(GOOGLE_USERINFO_URL, {
162	      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
163	      cache: "no-store",
164	    });
165	  } catch {
166	    return { error: "Couldn't reach Google to read your profile. Try again shortly." };
167	  }
168	
169	  let parsed: UserinfoResponse | null = null;
170	  try {
171	    parsed = (await res.json()) as UserinfoResponse;
172	  } catch {
173	    parsed = null;
174	  }
175	
176	  if (!res.ok || !parsed?.sub || !parsed?.email) {
177	    return { error: "Google didn't return your profile. Please try again." };
178	  }
179	
180	  const emailVerified = parsed.email_verified === true || parsed.email_verified === "true";
181	  return {
182	    profile: {
183	      sub: parsed.sub,
184	      email: parsed.email,
185	      emailVerified,
186	      name: (parsed.name ?? parsed.given_name ?? parsed.email.split("@")[0] ?? "").trim(),
187	      picture: parsed.picture ?? null,
188	    },
189	  };
190	}
