1	"use client";
2	
3	import { useActionState, useEffect, useState } from "react";
4	import Link from "next/link";
5	import { login, register } from "@/lib/actions";
6	
7	/**
8	 * The three rules `register()` in lib/actions.ts ACTUALLY enforces, restated
9	 * here so the checklist and the server agree.
10	 *
11	 * They used to disagree in both directions: the list demanded "Upper &
12	 * lowercase" and "A symbol" — neither of which the server checks — and never
13	 * mentioned the digit rule that it does. `PASSWORD!` therefore scored "Good"
14	 * and was rejected, while `abcdefg1` was accepted with two ticks missing. A
15	 * checklist that grades against rules nobody enforces is worse than no
16	 * checklist: it teaches the customer that the ticks are noise.
17	 *
18	 * If the regexes in `register()` change, change these with them.
19	 */
20	const REQUIRED_RULES = [
21	  { test: (v: string) => v.length >= 8, label: "8+ characters" },
22	  { test: (v: string) => /[a-zA-Z]/.test(v), label: "A letter" },
23	  { test: (v: string) => /[0-9]/.test(v), label: "A number" },
24	];
25	
26	/** Genuinely optional — these make a password stronger but never reject it. */
27	const BONUS_RULES = [
28	  { test: (v: string) => /[a-z]/.test(v) && /[A-Z]/.test(v), label: "Upper & lowercase" },
29	  { test: (v: string) => /[^A-Za-z0-9]/.test(v), label: "A symbol" },
30	];
31	
32	function PasswordField({
33	  id = "password",
34	  label = "Password",
35	  autoComplete = "new-password",
36	  requireStrong = true,
37	}: {
38	  id?: string;
39	  label?: string;
40	  autoComplete?: string;
41	  requireStrong?: boolean;
42	}) {
43	  const [val, setVal] = useState("");
44	  const [show, setShow] = useState(false);
45	  const required = REQUIRED_RULES.map((r) => ({ ok: r.test(val), label: r.label }));
46	  const bonus = BONUS_RULES.map((r) => ({ ok: r.test(val), label: r.label }));
47	  const score = [...required, ...bonus].filter((c) => c.ok).length;
48	  const strengthLabel = ["Too weak", "Too weak", "Weak", "Fair", "Good", "Strong"][score] ?? "Too weak";
49	  const barColor =
50	    ["bg-red-500", "bg-red-500", "bg-red-500", "bg-amber-500", "bg-yellow-400", "bg-emerald-500"][score] ??
51	    "bg-red-500";
52	  const total = required.length + bonus.length;
53	  return (
54	    <div>
55	      <label className="label" htmlFor={id}>{label}</label>
56	      <div className="relative">
57	        <input
58	          id={id}
59	          className="input pr-11"
60	          name="password"
61	          type={show ? "text" : "password"}
