219	export function LoginForm({
220	  next,
221	  googleEnabled = false,
222	  googleError,
223	  discordEnabled = false,
224	  discordError,
225	  showRegisterLink = true,
226	}: {
227	  next?: string;
228	  googleEnabled?: boolean;
229	  googleError?: string;
230	  discordEnabled?: boolean;
231	  discordError?: string;
232	  showRegisterLink?: boolean;
233	} = {}) {
234	  const [state, action, pending] = useActionState(login, {});
235	  const [email, setEmail] = useState("");
236	  const [code, setCode] = useState("");
237	  // `useActionState` hands back a NEW state object on every completed submit, so
238	  // this runs once per attempt. Still on the 2FA step and carrying an error =>
239	  // the code we just sent was empty or wrong; either way the box should start
240	  // clean for the next 30-second window. A no-op on the first challenge.
241	  useEffect(() => {
242	    if (state?.needs2fa && state?.error) setCode("");
243	  }, [state]);
244	  return (
245	    <div className="space-y-4">
246	      {/* An error bounced back from the Google/Discord OAuth routes (see app/login/page.tsx). */}
247	      <ErrorBox error={googleError} />
248	      <ErrorBox error={discordError} />
249	      {googleEnabled ? <GoogleButton next={next} /> : null}
250	      {discordEnabled ? <DiscordButton next={next} /> : null}
251	      {googleEnabled || discordEnabled ? <OrDivider /> : null}
252	      <form action={action} className="space-y-4">
253	        {/*
254	        Where the visitor was heading. Re-validated by `safeNext` in
255	        lib/actions.ts before any redirect — an unvalidated `next` on a login
256	        form is an open redirect and therefore a phishing primitive, so this
257	        value is carried, never trusted.
258	      */}
259	        {next ? <input type="hidden" name="next" value={next} /> : null}
260	        <ErrorBox error={state?.error} />
261	      <div>
262	        <label className="label" htmlFor="login-email">Email</label>
263	        <input
264	          id="login-email"
265	          className="input"
266	          name="email"
267	          type="email"
268	          required
269	          autoComplete="email"
270	          value={email}
271	          onChange={(e) => setEmail(e.target.value)}
272	        />
273	      </div>
274	      <PasswordField id="login-password" label="Password" autoComplete="current-password" requireStrong={false} />
275	      {state?.needs2fa && (
276	        <div>
277	          <label className="label" htmlFor="login-2fa-code">2FA code</label>
278	          {/* Controlled like the rest, so nothing here depends on React's reset
279	              behaviour. A rejected code is cleared DELIBERATELY below (a TOTP
280	              code is single-use and time-boxed, so keeping a stale one in the
281	              box only makes the customer clear it themselves) — the point is
282	              that the clearing is a decision, not a side effect. */}
283	          <input
284	            id="login-2fa-code"
285	            className="input tracking-[0.3em]"
286	            name="code"
287	            inputMode="numeric"
288	            autoComplete="one-time-code"
289	            placeholder="123456"
290	            autoFocus
291	            value={code}
292	            onChange={(e) => setCode(e.target.value)}
293	          />
294	          <p className="mt-1 text-xs text-slate-500">Enter the 6-digit code from your authenticator app, or a backup code.</p>
295	        </div>
296	      )}
297	      <button className="btn-primary w-full" disabled={pending}>
298	        {pending ? "Signing in…" : state?.needs2fa ? "Verify & sign in" : "Sign in"}
299	      </button>
300	      <div className={`flex items-center text-sm text-slate-400 ${showRegisterLink ? "justify-between" : "justify-end"}`}>
301	        {showRegisterLink && (
302	          <Link href={next ? `/register?next=${encodeURIComponent(next)}` : "/register"} className="text-brand-300 hover:underline">
303	            Create account
304	          </Link>
305	        )}
306	        <Link href="/forgot-password" className="hover:text-slate-200 hover:underline">
307	          Forgot password?
308	        </Link>
309	      </div>
310	      </form>
311	    </div>
312	  );
313	}
