324	  googleError?: string;
325	  discordEnabled?: boolean;
326	  discordError?: string;
327	} = {}) {
328	  const [state, action, pending] = useActionState(register, {});
329	  // Controlled for the same reason as the login form: a rejected signup used to
330	  // blank the name and the email, so a customer told "password must include a
331	  // number" had to retype their whole identity to act on it. Nothing a customer
332	  // typed is thrown away by a rejection.
333	  const [name, setName] = useState("");
334	  const [email, setEmail] = useState("");
335	  return (
336	    <div className="space-y-4">
337	      {/* Google/Discord OAuth create the account on first sign-in, so the same
338	          buttons double as sign-up here. Errors bounced back from the OAuth
339	          routes surface via googleError/discordError (see app/register/page.tsx). */}
340	      <ErrorBox error={googleError} />
341	      <ErrorBox error={discordError} />
342	      {googleEnabled ? <GoogleButton next={next} /> : null}
343	      {discordEnabled ? <DiscordButton next={next} /> : null}
344	      {googleEnabled || discordEnabled ? <OrDivider /> : null}
345	      <form action={action} className="space-y-4">
346	        {next ? <input type="hidden" name="next" value={next} /> : null}
347	        <ErrorBox error={state?.error} />
348	      <div>
349	        <label className="label" htmlFor="register-name">Name</label>
350	        <input
351	          id="register-name"
352	          className="input"
353	          name="name"
354	          required
355	          autoComplete="name"
356	          value={name}
357	          onChange={(e) => setName(e.target.value)}
358	        />
359	      </div>
360	      <div>
361	        <label className="label" htmlFor="register-email">Email</label>
362	        <input
363	          id="register-email"
364	          className="input"
365	          name="email"
366	          type="email"
367	          required
368	          autoComplete="email"
369	          value={email}
370	          onChange={(e) => setEmail(e.target.value)}
371	        />
372	      </div>
373	      <PasswordField id="register-password" />
374	      <button className="btn-primary w-full" disabled={pending}>
375	        {pending ? "Creating account…" : "Create account"}
376	      </button>
377	      <p className="text-center text-sm text-slate-400">
378	        Already registered?{" "}
379	        <Link href="/login" className="text-brand-300 hover:underline">
