53	  // Already signed in? Then this page is just a waypoint: send them where they
54	  // were going. Without this, a public CTA written as `/login?next=/dashboard/x`
55	  // would strand EXISTING customers on a sign-in form they do not need — trading
56	  // one dead end for a worse one, since it asks a paying customer to authenticate
57	  // twice.
58	  const user = await currentUser();
59	  if (user) redirect(dest ?? roleHome(user.role));
60	
61	  return (
62	    <AuthShell
63	      heading="Welcome back"
64	      sub="Sign in to manage your servers and billing."
65	      bullets={[
66	        "Instant NVMe VPS provisioning",
67	        "Real-time metrics and one-click reinstalls",
68	        "Full root access on every plan",
69	      ]}
70	    >
71	      {/* The VALIDATED destination, never the raw query value: a rejected
72	          `next` must not be echoed into the DOM at all. It could not cause a
73	          redirect (the action re-validates), but rendering attacker-supplied
74	          text into a form for no reason is how the next bug starts. */}
75	      <LoginForm
76	        next={dest ?? undefined}
77	        googleEnabled={googleOauthConfigured()}
78	        googleError={googleError}
79	        discordEnabled={discordEnabled}
80	        discordError={discordError}
81	      />
82	    </AuthShell>
