44	/**
45	 * Step 2 of "Login with Google": the OAuth redirect target.
46	 *
47	 * Verifies CSRF `state` against the httpOnly cookie, exchanges the code for a
48	 * token, reads the OIDC profile, then finds/links/creates the local account and
49	 * issues the SAME session cookie a normal password login does (`createSession`).
50	 * No token is ever logged or placed in a URL. Any failure redirects to /login
51	 * with a friendly `error` code.
52	 *
53	 * NOTE: this is a Route Handler, NOT a `"use server"` action, so it adds no new
54	 * server-action endpoint and the customer-action guard test is unaffected.
55	 */
56	export async function GET(req: NextRequest) {
57	  if (!googleOauthConfigured()) return fail("google_unavailable");
58	
59	  const raw = req.cookies.get(STATE_COOKIE)?.value;
60	  let stash: Stash = {};
61	  try {
62	    stash = raw ? (JSON.parse(raw) as Stash) : {};
63	  } catch {
64	    stash = {};
65	  }
66	  const next = safeNext(stash.next ?? null);
67	
68	  const sp = req.nextUrl.searchParams;
69	
70	  // The user declined on Google's consent screen, or Google itself errored
71	  // (e.g. the app is still in "testing" mode and this user isn't a test user).
