85	
86	  const exchanged = await googleExchangeCode(code);
87	  if (!exchanged.accessToken) return fail("google_error");
88	
89	  const { profile } = await googleFetchProfile(exchanged.accessToken);
90	  if (!profile) return fail("google_error");
91	
92	  // Google must have verified control of the address, else linking/creating an
93	  // account on it would trust an address the user never proved they own.
94	  if (!profile.emailVerified) return fail("google_unverified");
95	
96	  const email = normalizeEmail(profile.email);
97	  if (!email) return fail("google_error");
98	
99	  // 1) Existing Google link → sign in.
100	  let user = await db.user.findUnique({ where: { googleId: profile.sub } });
101	
102	  // 2) Existing account by email → link Google onto it (lets a password user
103	  //    sign in with Google). Google already verified the address, so also stamp
104	  //    email verification if it was never proven locally.
105	  if (!user) {
106	    const byEmail = await db.user.findUnique({ where: { email } });
107	    if (byEmail) {
108	      user = await db.user.update({
109	        where: { id: byEmail.id },
110	        data: {
111	          googleId: profile.sub,
112	          avatarUrl: byEmail.avatarUrl ?? profile.picture,
113	          emailVerifiedAt: byEmail.emailVerifiedAt ?? new Date(),
114	        },
115	      });
116	      await db.auditLog
117	        .create({ data: { userId: user.id, action: "user.google_link", detail: "Linked Google to existing account" } })
118	        .catch(() => {});
119	    }
120	  }
121	
122	  // 3) No account yet → create one. `passwordHash` is required and this account
123	  //    has no password, so store a random, unusable bcrypt hash: it can never
124	  //    match any input, so the account can't be password-logged-in until the
125	  //    user sets a password (via forgot-password). Google verified the email, so
126	  //    it starts verified.
127	  if (!user) {
