129	    try {
130	      user = await db.user.create({
131	        data: {
132	          email,
133	          name: profile.name || email.split("@")[0] || "Nxeon user",
134	          passwordHash: unusableHash,
135	          googleId: profile.sub,
136	          avatarUrl: profile.picture,
137	          emailVerifiedAt: new Date(),
