161	        });
162	        if (claimed.count > 0) {
163	          await db.walletTransaction.create({ data: { userId: user.id, amountCents: cents, description: "Welcome credit" } });
164	        }
165	      }
166	    } catch (e) {
167	      console.error("[google] signup credit grant failed for", user.id, e);
168	    }
169	    try {
170	      const { sendMail, emails } = await import("@/lib/mailer");
171	      const tpl = emails.welcome(user.name || "");
172	      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
173	    } catch {
