25	  const ip = clientIp(req.headers);
26	  const rl = checkRateLimit(`discord-auth-start:${ip}`, { max: 20, windowMs: 60_000 });
27	  if (!rl.ok) {
28	    return NextResponse.redirect(`${base()}/login?error=discord_ratelimited`);
