6	  discordCustomerOauthRedirectUri,
7	  discordExchangeCode,
8	  fetchDiscordSelf,
9	  peekDiscordState,
10	  verifyDiscordOauthState,
11	} from "@/lib/discord-oauth";
12	import { syncDiscordRoles } from "@/lib/discord-roles";
13	import { loginOrSignupWithDiscord } from "@/lib/discord-auth";
14	
15	export const dynamic = "force-dynamic";
16	
17	const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
18	
19	const isUniqueConflict = (e: unknown): boolean => (e as { code?: string } | null)?.code === "P2002";
20	
21	/**
22	 * ONE callback route for TWO flows, distinguished purely by the signed
23	 * state's `typ` (see lib/discord-oauth.ts's peekDiscordState) — this is
24	 * what let Phase F ("Continue with Discord" login/signup,
25	 * app/api/discord/login/route.ts) ship without a second redirect URI to
26	 * register on the Discord application:
27	 *
28	 *   - typ === discord_oauth_state → LINK flow: an ALREADY-signed-in
29	 *     customer connecting their Discord account (see
30	 *     app/api/discord/authorize/route.ts). Mirrors
31	 *     app/api/admin/discord/callback/route.ts's identity/CSRF discipline.
32	 *   - typ === discord_auth_state  → AUTH flow: no session yet — log in (if
33	 *     this Discord account is already linked) or create a new account (if
34	 *     Discord gave a verified email that matches nothing) — see
35	 *     lib/discord-auth.ts's loginOrSignupWithDiscord for the security
36	 *     reasoning on that branch specifically.
37	 */
38	export async function GET(req: NextRequest) {
39	  const sp = req.nextUrl.searchParams;
40	
41	  const oauthError = sp.get("error");
42	  const state = sp.get("state");
43	  const peek = await peekDiscordState(state);
44	
45	  // We don't know which flow this was for an invalid/expired state (peek
46	  // failed before even reading typ) — /login is the safe default landing
47	  // spot either way (an already-signed-in visitor bouncing through it is
48	  // harmless; the settings page requires a session it will already have).
49	  if (oauthError || !peek.ok) {
50	    const code = oauthError ? (oauthError === "access_denied" ? "discord_cancelled" : "discord_error") : "discord_state";
51	    return NextResponse.redirect(`${base()}/login?error=${code}`);
52	  }
53	
54	  if (peek.typ === AUTH_STATE_TYP) {
55	    return handleAuthCallback(sp, peek.next);
56	  }
57	  return handleLinkCallback(sp, state);
58	}
59	
60	// ---------------------------------------------------------------------------
61	// AUTH flow — unauthenticated login/signup
62	// ---------------------------------------------------------------------------
63	
64	async function handleAuthCallback(sp: URLSearchParams, next?: string): Promise<NextResponse> {
65	  const fail = (code: string) => NextResponse.redirect(`${base()}/login?error=${code}`);
66	
67	  const code = sp.get("code");
68	  if (!code) return fail("discord_error");
69	
70	  const exchanged = await discordExchangeCode(code, discordCustomerOauthRedirectUri());
71	  if (!exchanged.accessToken) return fail("discord_error");
72	
73	  const identified = await fetchDiscordSelf(exchanged.accessToken);
74	  if (!identified.user) return fail("discord_error");
75	
76	  const result = await loginOrSignupWithDiscord(identified.user, exchanged.accessToken);
77	  if (!result.ok) return fail(result.error);
78	
79	  const dest = next && next !== "/login" && next !== "/register" ? next : "/dashboard";
80	  return NextResponse.redirect(`${base()}${dest}`);
81	}
82	
83	// ---------------------------------------------------------------------------
84	// LINK flow — an already-signed-in customer connecting their account
85	// ---------------------------------------------------------------------------
86	
87	function redirectWith(params: Record<string, string>): NextResponse {
88	  const url = new URL(`${base()}/dashboard/settings`);
89	  url.searchParams.set("tab", "integrations");
90	  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
91	  return NextResponse.redirect(url.toString());
92	}
93	
94	async function handleLinkCallback(sp: URLSearchParams, state: string | null): Promise<NextResponse> {
95	  const fail = (msg: string) => redirectWith({ discord: "error", discordmsg: msg });
96	
97	  const me = await realUser();
98	  if (!me) return fail("You're not signed in — sign in again and retry from Settings.");
99	
100	  const stateCheck = await verifyDiscordOauthState(state, me.id);
101	  if (!stateCheck.ok) return fail(stateCheck.error);
102	
103	  const code = sp.get("code");
104	  if (!code) return fail("Discord didn't return an authorization code. Please try connecting again.");
105	
106	  const exchanged = await discordExchangeCode(code, discordCustomerOauthRedirectUri());
107	  if (!exchanged.accessToken) return fail(exchanged.error ?? "Couldn't complete the Discord connection. Please try again.");
108	
109	  const identified = await fetchDiscordSelf(exchanged.accessToken);
110	  if (!identified.user) return fail(identified.error ?? "Couldn't confirm your Discord account. Please try again.");
111	
112	  try {
113	    await db.user.update({ where: { id: me.id }, data: { discordUserId: identified.user.id } as any });
114	  } catch (e) {
115	    if (isUniqueConflict(e)) return fail("This Discord account is already linked to another Nxeon account.");
116	    console.error("[discord-oauth] failed to store discordUserId for", me.id, e);
117	    return fail("Couldn't save the Discord connection right now. Please try again shortly.");
118	  }
119	
120	  await db.auditLog
121	    .create({ data: { userId: me.id, action: "discord.link", detail: identified.user.username || identified.user.id } })
122	    .catch(() => {});
123	
124	  void syncDiscordRoles(me.id);
125	
126	  return redirectWith({ discord: "connected" });
127	}
